function isRecord(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function string(value, maximum = 512) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed && trimmed.length <= maximum ? trimmed : null;
}

function integer(value, fallback = 0) {
  return Number.isFinite(value) ? Math.floor(value) : fallback;
}

function providerKey(value) {
  return string(value, 100)?.toLowerCase() ?? null;
}

function key(provider, agentId) {
  return `${provider}\u0000${agentId}`;
}

function normalizeScope(raw, hostId) {
  if (!isRecord(raw) || string(raw.hostId, 63) !== hostId) return null;
  const provider = providerKey(raw.provider);
  const model = string(raw.model, 240);
  const agentIds = [...new Set((Array.isArray(raw.agentIds) ? raw.agentIds : [])
    .map((agentId) => string(agentId, 128))
    .filter(Boolean))].sort();
  if (!provider || !model || agentIds.length === 0) return null;
  return {
    provider,
    model,
    agentIds,
    strict: raw.strict !== false,
    managedProfileIds: [...new Set((Array.isArray(raw.managedProfileIds) ? raw.managedProfileIds : [])
      .map((profileId) => string(profileId, 240))
      .filter(Boolean))],
  };
}

function normalizeAssignment(raw, hostId) {
  if (!isRecord(raw) || string(raw.hostId, 63) !== hostId) return null;
  const provider = providerKey(raw.provider);
  const model = string(raw.model, 240);
  const agentId = string(raw.agentId, 128);
  const status = raw.status === "ASSIGNED" || raw.status === "UNASSIGNED" ? raw.status : null;
  const mode = raw.mode === "enforce" || raw.mode === "shadow" ? raw.mode : null;
  const epoch = integer(raw.epoch, -1);
  if (!provider || !model || !agentId || !status || !mode || epoch < 0) return null;
  const profileId = status === "ASSIGNED" ? string(raw.profileId, 240) : null;
  const digest = status === "ASSIGNED" ? string(raw.digest, 128) : null;
  const leaseId = status === "ASSIGNED" ? string(raw.leaseId, 128) : null;
  if (status === "ASSIGNED" && (!profileId || !digest || !leaseId)) return null;
  return {
    provider,
    model,
    agentId,
    profileId,
    digest,
    leaseId,
    status,
    reason: string(raw.reason, 128),
    mode,
    epoch,
    expiresAt: Math.max(0, integer(raw.expiresAt)),
  };
}

function normalizeRefreshLease(raw, hostId) {
  if (!isRecord(raw)) return null;
  const provider = providerKey(raw.provider);
  const profileId = string(raw.profileId, 240);
  const digest = string(raw.digest, 128);
  const holderHost = string(raw.holderHost, 63);
  const leaseId = string(raw.leaseId, 128);
  const epoch = integer(raw.epoch, -1);
  const expiresAt = Math.max(0, integer(raw.expiresAt));
  if (!provider || !profileId || !digest || !holderHost || !leaseId || epoch < 0 || expiresAt === 0) return null;
  // A client must only act on a lease explicitly held by itself.  Keeping
  // other holders in the normalized document is useful for diagnostics, but
  // never turns them into local authority.
  return { provider, profileId, digest, holderHost, leaseId, epoch, expiresAt, local: holderHost === hostId };
}

/** Parse the non-secret document a client is allowed to read from OpenBao. */
export function normalizeLeaseAssignments(raw, { hostId, now = Date.now() } = {}) {
  const normalizedHostId = string(hostId, 63);
  if (!normalizedHostId || !isRecord(raw) || raw.schemaVersion !== 1) {
    return { generation: 0, scopes: [], assignments: new Map(), now };
  }
  const scopes = (Array.isArray(raw.scopes) ? raw.scopes : [])
    .map((scope) => normalizeScope(scope, normalizedHostId))
    .filter(Boolean);
  const scopeKeys = new Set(scopes.map((scope) => `${scope.provider}\u0000${scope.model}`));
  const assignments = new Map();
  for (const rawAssignment of Array.isArray(raw.assignments) ? raw.assignments : []) {
    const assignment = normalizeAssignment(rawAssignment, normalizedHostId);
    if (!assignment || !scopeKeys.has(`${assignment.provider}\u0000${assignment.model}`)) continue;
    const assignmentKey = key(assignment.provider, assignment.agentId);
    const previous = assignments.get(assignmentKey);
    if (!previous || assignment.epoch > previous.epoch || (assignment.epoch === previous.epoch && assignment.model < previous.model)) {
      assignments.set(assignmentKey, assignment);
    }
  }
  const refreshLeases = new Map();
  for (const rawRefreshLease of Array.isArray(raw.refreshLeases) ? raw.refreshLeases : []) {
    const refreshLease = normalizeRefreshLease(rawRefreshLease, normalizedHostId);
    if (!refreshLease) continue;
    const refreshKey = `${refreshLease.provider}\u0000${refreshLease.profileId}\u0000${refreshLease.digest}`;
    const previous = refreshLeases.get(refreshKey);
    if (!previous || refreshLease.epoch > previous.epoch) refreshLeases.set(refreshKey, refreshLease);
  }
  return {
    generation: Math.max(0, integer(raw.generation)),
    scopes,
    assignments,
    refreshLeases,
    now,
  };
}

/** Return an explicit ASSIGNED/UNASSIGNED/EXPIRED grant for one controlled agent. */
export function leaseAssignmentForAgent(document, { provider, agentId, now = Date.now() } = {}) {
  const normalizedProvider = providerKey(provider);
  const normalizedAgentId = string(agentId, 128);
  if (!normalizedProvider || !normalizedAgentId) return null;
  const scope = document?.scopes?.find(
    (candidate) => candidate.provider === normalizedProvider && candidate.agentIds.includes(normalizedAgentId),
  );
  if (!scope) return null;
  const assignment = document.assignments?.get(key(normalizedProvider, normalizedAgentId));
  if (!assignment) {
    return { provider: normalizedProvider, agentId: normalizedAgentId, model: scope.model, status: "UNASSIGNED", reason: "lease_missing", epoch: 0, mode: "shadow" };
  }
  if (assignment.status === "ASSIGNED" && assignment.expiresAt <= now) {
    return { ...assignment, profileId: null, digest: null, leaseId: null, status: "EXPIRED", reason: "lease_expired" };
  }
  return assignment;
}

/**
 * Refresh is a global side effect: allow it only when this exact credential
 * generation is covered by an unexpired lease held by this host.  The helper
 * deliberately matches digest, so a rotated credential cannot inherit an old
 * refresh grant.
 */
export function hasRefreshLease(raw, { hostId, provider, profileId, digest, now = Date.now() } = {}) {
  const document = normalizeLeaseAssignments(raw, { hostId, now });
  const normalizedProvider = providerKey(provider);
  const normalizedProfileId = string(profileId, 240);
  const normalizedDigest = string(digest, 128);
  if (!normalizedProvider || !normalizedProfileId || !normalizedDigest) return false;
  const refreshLease = document.refreshLeases.get(
    `${normalizedProvider}\u0000${normalizedProfileId}\u0000${normalizedDigest}`,
  );
  return Boolean(refreshLease?.local && refreshLease.expiresAt > now);
}

import { classifyPermanentRefreshFailure } from "./bad-refresh-quarantine.js";

function isRecord(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function normalizeProvider(value) {
  return typeof value === "string" && value.trim() ? value.trim().toLowerCase() : null;
}

function retryAfterMs(message) {
  const seconds = message.match(/retry[- ]after[^0-9]*(\d+(?:\.\d+)?)\s*s(?:econds?)?/i)?.[1];
  if (!seconds) return null;
  return Math.max(15_000, Math.min(6 * 60 * 60_000, Math.round(Number(seconds) * 1000)));
}

function providerFromMessage(message) {
  return normalizeProvider(message.match(/(?:for|provider[=:])\s*([a-z0-9_-]+)/i)?.[1]);
}

/**
 * Classify a provider failure into a central health action.  Unknown errors are
 * deliberately ignored; ambiguity must never eject a shared credential.
 */
export function classifyProviderFailure(value) {
  const message = value instanceof Error ? value.message : typeof value === "string" ? value : "";
  if (!message) return null;
  const permanent = classifyPermanentRefreshFailure(message);
  if (permanent) return { classification: "auth_permanent", provider: permanent.provider, reason: permanent.reason };
  if (/\b(?:429|too many requests|rate limit(?:ed)?|quota (?:exceeded|limit)|insufficient_quota)\b/i.test(message)) {
    return { classification: "rate_limited", provider: providerFromMessage(message), reason: "rate_limited", retryAfterMs: retryAfterMs(message) };
  }
  if (/\b(?:503|overloaded|service unavailable|capacity temporarily unavailable)\b/i.test(message)) {
    return { classification: "overloaded", provider: providerFromMessage(message), reason: "overloaded", retryAfterMs: retryAfterMs(message) };
  }
  if (/\b(?:model_not_found|unsupported model|model .*?(?:not found|not supported)|does not support model)\b/i.test(message)) {
    return { classification: "unsupported_model", provider: providerFromMessage(message), reason: "unsupported_model" };
  }
  if (/\b(?:ENOTFOUND|EAI_AGAIN|ECONNREFUSED|ECONNRESET|ETIMEDOUT|network is unreachable|dns(?: lookup)? failed)\b/i.test(message)) {
    return { classification: "local_network", provider: providerFromMessage(message), reason: "local_network", retryAfterMs: 30_000 };
  }
  return null;
}

function credentialMatchesProvider(credential, provider) {
  if (!isRecord(credential) || typeof credential.provider !== "string") return false;
  return !provider || credential.provider.trim().toLowerCase() === provider;
}

/** Resolve one profile only when the gateway's usage-state timing is unambiguous. */
export function selectRecentlyFailedProfile(store, provider, eventTs, options = {}) {
  if (!isRecord(store) || !isRecord(store.profiles) || !isRecord(store.usageStats)) return null;
  const timestamp = Number(eventTs);
  if (!Number.isFinite(timestamp)) return null;
  const maxAgeMs = Number.isFinite(options.maxAgeMs) ? Math.max(0, options.maxAgeMs) : 30_000;
  const futureSkewMs = Number.isFinite(options.futureSkewMs) ? Math.max(0, options.futureSkewMs) : 5_000;
  const normalizedProvider = normalizeProvider(provider);
  const candidates = [];
  for (const [profileId, credential] of Object.entries(store.profiles)) {
    if (!credentialMatchesProvider(credential, normalizedProvider)) continue;
    const usage = store.usageStats[profileId];
    const lastFailureAt = Number(usage?.lastFailureAt);
    if (!Number.isFinite(lastFailureAt)) continue;
    const age = timestamp - lastFailureAt;
    if (age > maxAgeMs || age < -futureSkewMs) continue;
    candidates.push({ profileId, credential, lastFailureAt, distanceMs: Math.abs(age) });
  }
  candidates.sort((left, right) => left.distanceMs - right.distanceMs || right.lastFailureAt - left.lastFailureAt);
  if (candidates.length === 0) return null;
  if (candidates.length > 1 && candidates[0].distanceMs === candidates[1].distanceMs) return null;
  return candidates[0];
}

export function lifecycleErrorText(event) {
  if (!isRecord(event?.data)) return "";
  return [event.data.error, event.data.errorMessage, event.data.message, event.data.detail]
    .filter((value) => typeof value === "string" && value.trim())
    .join("\n");
}

export function lifecycleAgentId(event) {
  if (typeof event?.agentId === "string" && event.agentId.trim()) return event.agentId.trim();
  if (typeof event?.sessionKey !== "string") return null;
  return event.sessionKey.match(/^agent:([^:]+):/)?.[1] ?? null;
}

export function lifecycleModel(event) {
  const direct = event?.data?.model ?? event?.data?.modelId ?? event?.model ?? event?.modelId;
  return typeof direct === "string" && direct.trim() ? direct.trim() : null;
}

const PERMANENT_REFRESH_REASONS = [
  ["refresh_token_reused", /refresh_token_reused|refresh token has already been used|already been used to generate a new access token/i],
  ["invalid_refresh_token", /invalid_refresh_token|invalid refresh token/i],
  ["token_invalidated", /token_invalidated/i],
  ["invalid_grant", /invalid_grant/i],
  ["revoked", /refresh token[^\n]*(?:expired or revoked|revoked)/i],
];

function isRecord(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function normalizeProvider(provider) {
  return typeof provider === "string" ? provider.trim().toLowerCase() : "";
}

/** Classify only refresh failures that cannot recover by retrying the same credential. */
export function classifyPermanentRefreshFailure(value) {
  const message = value instanceof Error ? value.message : typeof value === "string" ? value : "";
  if (!message) return null;
  const lower = message.toLowerCase();
  const isRefreshFailure =
    lower.includes("oauth token refresh failed") ||
    lower.includes("auth refresh request failed") ||
    lower.includes("access token could not be refreshed") ||
    lower.includes("authentication session could not be refreshed automatically");
  if (!isRefreshFailure) return null;
  const matched = PERMANENT_REFRESH_REASONS.find(([, pattern]) => pattern.test(message));
  if (!matched) return null;
  const providerMatch = message.match(/OAuth token refresh failed for\s+([^:\s]+)\s*:/i);
  return { provider: normalizeProvider(providerMatch?.[1]) || null, reason: matched[0] };
}

function credentialMatchesProvider(credential, provider) {
  if (!isRecord(credential) || credential.type !== "oauth") return false;
  const expected = normalizeProvider(provider);
  return !expected || normalizeProvider(credential.provider) === expected;
}

/**
 * Resolve one exact profile after a terminal refresh error.  An ambiguous tie
 * deliberately returns null rather than risking a healthy account.
 */
export function selectRecentlyFailedOAuthProfile(store, provider, eventTs, options = {}) {
  if (!isRecord(store) || !isRecord(store.profiles) || !isRecord(store.usageStats)) return null;
  const timestamp = Number(eventTs);
  if (!Number.isFinite(timestamp)) return null;
  const maxAgeMs = Number.isFinite(options.maxAgeMs) ? Math.max(0, options.maxAgeMs) : 30_000;
  const futureSkewMs = Number.isFinite(options.futureSkewMs) ? Math.max(0, options.futureSkewMs) : 5_000;
  const candidates = [];
  for (const [profileId, credential] of Object.entries(store.profiles)) {
    if (!credentialMatchesProvider(credential, provider)) continue;
    const usage = store.usageStats[profileId];
    if (!isRecord(usage)) continue;
    const lastFailureAt = Number(usage.lastFailureAt);
    if (!Number.isFinite(lastFailureAt)) continue;
    const permanent = usage.disabledReason === "auth_permanent" || Number(usage.failureCounts?.auth_permanent) > 0;
    if (!permanent) continue;
    const ageMs = timestamp - lastFailureAt;
    if (ageMs > maxAgeMs || ageMs < -futureSkewMs) continue;
    candidates.push({ profileId, credential, lastFailureAt, distanceMs: Math.abs(ageMs) });
  }
  candidates.sort((left, right) => left.distanceMs - right.distanceMs || right.lastFailureAt - left.lastFailureAt);
  if (candidates.length === 0) return null;
  if (candidates.length > 1 && candidates[0].distanceMs === candidates[1].distanceMs) return null;
  return candidates[0];
}

/** Remove a profile and its state pointers without disturbing independent fallbacks. */
export function removeProfileAndReferences(store, profileId) {
  if (!isRecord(store) || !isRecord(store.profiles)) return false;
  let changed = false;
  if (store.profiles[profileId]) {
    delete store.profiles[profileId];
    changed = true;
  }
  if (isRecord(store.order)) {
    for (const [provider, order] of Object.entries(store.order)) {
      if (!Array.isArray(order) || !order.includes(profileId)) continue;
      const next = order.filter((candidate) => candidate !== profileId);
      if (next.length > 0) store.order[provider] = next;
      else delete store.order[provider];
      changed = true;
    }
    if (Object.keys(store.order).length === 0) store.order = undefined;
  }
  if (isRecord(store.lastGood)) {
    for (const [provider, candidate] of Object.entries(store.lastGood)) {
      if (candidate !== profileId) continue;
      delete store.lastGood[provider];
      changed = true;
    }
    if (Object.keys(store.lastGood).length === 0) store.lastGood = undefined;
  }
  if (isRecord(store.usageStats)) {
    if (store.usageStats[profileId]) {
      delete store.usageStats[profileId];
      changed = true;
    }
    if (Object.keys(store.usageStats).length === 0) store.usageStats = undefined;
  }
  return changed;
}

export function isDigestQuarantined(quarantine, profileId, digest) {
  const entry = quarantine instanceof Map ? quarantine.get(profileId) : null;
  return Boolean(entry && typeof digest === "string" && entry.digest === digest);
}

/** A re-login changes digest and therefore releases only that old generation. */
export function reconcileQuarantineWithManifest(quarantine, manifestById) {
  let changed = false;
  for (const [profileId, entry] of quarantine) {
    const manifestEntry = manifestById.get(profileId);
    if (manifestEntry?.digest === entry.digest) continue;
    quarantine.delete(profileId);
    changed = true;
  }
  return changed;
}

export function selectPendingRuntimeRefreshes(localProfiles, manifestById, applied) {
  const pending = new Map();
  for (const [profileId, candidate] of localProfiles) {
    const manifestEntry = manifestById.get(profileId);
    if (!manifestEntry || candidate.digest === manifestEntry.digest) continue;
    if (applied.get(profileId) !== manifestEntry.digest) continue;
    if (candidate.identity !== manifestEntry.identity) continue;
    if (candidate.credential?.type !== "oauth" || manifestEntry.type !== "oauth") continue;
    const localExpires = Number(candidate.credential.expires) || 0;
    const manifestExpires = Number(manifestEntry.expires) || 0;
    if (localExpires <= manifestExpires) continue;
    pending.set(profileId, candidate);
  }
  return pending;
}

export function expectedCredentialDigest(manifestEntry, pendingRuntimeRefreshes) {
  return pendingRuntimeRefreshes.get(manifestEntry.profileId)?.digest ?? manifestEntry.digest;
}

// The Codex extension owns its shared app-server clients in this process-wide
// state. AuthBus cannot import the extension directly because generated plugin
// paths differ across hosts, but the extension intentionally uses this stable
// Symbol.for key.
const SHARED_CODEX_APP_SERVER_CLIENT_STATE = Symbol.for("openclaw.codexAppServerClientState");

function nonNegativeCount(value) {
  return Number.isFinite(value) && value > 0 ? Math.floor(value) : 0;
}

/**
 * Retire every shared Codex app-server client without interrupting an active
 * lease. It removes entries immediately so new work gets freshly authenticated
 * clients, closes idle clients now, and marks leased clients for their normal
 * release path to close.
 */
export function retireSharedCodexAppServerClients() {
  const state = globalThis[SHARED_CODEX_APP_SERVER_CLIENT_STATE];
  if (!state || !(state.clients instanceof Map)) {
    return {
      available: false,
      retired: 0,
      closed: 0,
      deferred: 0,
      invalid: 0,
      closeErrors: 0,
    };
  }

  const result = {
    available: true,
    retired: 0,
    closed: 0,
    deferred: 0,
    invalid: 0,
    closeErrors: 0,
  };
  for (const [key, entry] of state.clients.entries()) {
    state.clients.delete(key);
    if (!entry || typeof entry !== "object") {
      result.invalid += 1;
      continue;
    }
    result.retired += 1;
    entry.closeWhenIdle = true;
    const activeLeases = nonNegativeCount(entry.activeLeases);
    const pendingAcquires = nonNegativeCount(entry.pendingAcquires);
    if (activeLeases > 0 || pendingAcquires > 0) {
      result.deferred += 1;
      continue;
    }
    const client = entry.client;
    if (!client || typeof client.close !== "function") {
      // A startup path can populate entry.client later; its pending-acquire
      // release hook observes closeWhenIdle and closes it.
      result.deferred += 1;
      continue;
    }
    entry.closeWhenIdle = false;
    entry.client = undefined;
    try {
      client.close();
      result.closed += 1;
    } catch {
      result.closeErrors += 1;
    }
  }
  return result;
}
